const DEFAULT_SETTINGS: SeoSettings = {
  global: DEFAULT_GLOBAL,
  pages: DEFAULT_PAGES,
  updatedAt: Date.now(),
};

function readLocalSeoSettings(): SeoSettings {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved) as SeoSettings;
      return {
        global: { ...DEFAULT_GLOBAL, ...parsed.global },
        pages: parsed.pages && parsed.pages.length > 0 ? parsed.pages : DEFAULT_PAGES,
        updatedAt: parsed.updatedAt || Date.now(),
      };
    }
  } catch {
    // ignore
  }
  return DEFAULT_SETTINGS;
}

export function useSeoSettings(options?: { preferRemote?: boolean }) {
  const preferRemote = options?.preferRemote ?? false;
  const remoteData = useRemoteDataStore<Partial<SeoSettings>>('seo');
  // 🔴 同步初始化：直接读 localStorage 作为初始值，避免首帧默认值 → 第二帧同值不同引用的重渲染
  const [settings, setSettings] = useState<SeoSettings>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved) as SeoSettings;
        return {
          global: { ...DEFAULT_GLOBAL, ...parsed.global },
          pages: parsed.pages && parsed.pages.length > 0 ? parsed.pages : DEFAULT_PAGES,
          updatedAt: parsed.updatedAt || Date.now(),
        };
      }
    } catch (err) {
      logger.warn('Failed to init SEO settings:', String(err));
    }
    return {
      global: DEFAULT_GLOBAL,
      pages: DEFAULT_PAGES,
      updatedAt: Date.now(),
    };
  });

  // loading 始终为 false：本地数据同步初始化完成
  const loading = false;

  // 监听跨 tab storage 事件 + 同 tab 自定义事件（Pull Data 后触发刷新）
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key !== STORAGE_KEY || !e.newValue) return;
      try {
        const parsed = JSON.parse(e.newValue) as SeoSettings;
        setSettings({
          global: { ...DEFAULT_GLOBAL, ...parsed.global },
          pages: parsed.pages && parsed.pages.length > 0 ? parsed.pages : DEFAULT_PAGES,
          updatedAt: parsed.updatedAt || Date.now(),
        });
        logger.info('[SEO Settings] Storage event received from another tab');
      } catch (err) {
        logger.warn('[SEO Settings] Failed to parse storage event:', String(err));
      }
    };

    const handleCustomChange = (e: Event) => {
      const detail = (e as CustomEvent<Partial<SeoSettings>>).detail;
      if (detail && typeof detail === 'object') {
        setSettings({
          global: { ...DEFAULT_GLOBAL, ...(detail.global ?? {}) },
          pages: Array.isArray(detail.pages) && detail.pages.length > 0 ? detail.pages : DEFAULT_PAGES,
          updatedAt: typeof detail.updatedAt === 'number' ? detail.updatedAt : Date.now(),
        });
        logger.info('[SEO Settings] CustomEvent received (seo-settings-change)');
      }
    };

    window.addEventListener('storage', handleStorageChange);
    window.addEventListener('seo-settings-change', handleCustomChange);
    return () => {
      window.removeEventListener('storage', handleStorageChange);
      window.removeEventListener('seo-settings-change', handleCustomChange);
    };
  }, []);

  const displaySettings = useMemo((): SeoSettings => {
    if (preferRemote && remoteData && typeof remoteData === 'object') {
      try {
        const r = remoteData as Record<string, unknown>;
        const g = (r.global ?? {}) as Record<string, unknown>;
        const p = r.pages;
        const pagesArr = Array.isArray(p) ? (p as SeoPageSettings[]) : DEFAULT_PAGES;
        return {
          global: { ...DEFAULT_GLOBAL, ...g },
          pages: pagesArr.length > 0 ? pagesArr : DEFAULT_PAGES,
          updatedAt: typeof r.updatedAt === 'number' ? r.updatedAt : Date.now(),
        };
      } catch (err) {
        logger.warn('[SEO Settings] remote data merge failed, falling back to local:', String(err));
      }
    }
    return settings;
  }, [preferRemote, remoteData, settings]);

  // Save to storage
  const saveSettings = useCallback((newSettings: SeoSettings) => {
    try {
      const toSave = { ...newSettings, updatedAt: Date.now() };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(toSave));
      setSettings(toSave);
      return true;
    } catch (err) {
      logger.error('Failed to save SEO settings:', String(err));
      return false;
    }
  }, []);

  const updateGlobal = useCallback((global: Partial<SeoGlobalSettings>) => {
    const updated = {
      ...settings,
      global: { ...settings.global, ...global },
    };
    return saveSettings(updated);
  }, [settings, saveSettings]);

  const updatePage = useCallback((pageKey: string, pageData: Partial<SeoPageSettings>) => {
    const updatedPages = settings.pages.map((p) =>
      p.pageKey === pageKey ? { ...p, ...pageData } : p
    );
    const updated = { ...settings, pages: updatedPages };
    return saveSettings(updated);
  }, [settings, saveSettings]);

  const getPageSettings = useCallback((pageKey: string): SeoPageSettings | undefined => {
    return settings.pages.find((p) => p.pageKey === pageKey);
  }, [settings.pages]);

  const resetToDefaults = useCallback(() => {
    return saveSettings(DEFAULT_SETTINGS);
  }, [saveSettings]);

  return {
    settings: displaySettings,
    loading,
    updateGlobal,
    updatePage,
    getPageSettings,
    resetToDefaults,
    saveSettings,
    isUsingRemoteData: preferRemote && !!remoteData,
  };
}
